def icon(name):
 return f'<svg class="icon" viewBox="0 0 48 48" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round">{ICONS[name]}</svg>'

def link(url,label,cls=''):
 return f'<a href="{esc(url,quote=True)}" class="{cls}">{label}</a>'
def button(label='Get a quote',url='/request-a-proposal/',cls=''):
 return link(url,label,'button '+cls)
def wa_url(text='Hello PanPan Marine, I would like to discuss an underwater equipment project.'):
 return f'https://wa.me/{WHATSAPP}?text={quote(text)}' if WHATSAPP else ''
def contact_buttons(cls='',quote_url='/request-a-proposal/'):
 out=button('Get a quote',quote_url,'lime '+cls)+link('mailto:'+EMAIL,'Email us','button outline '+cls)
 if WHATSAPP: out+=f'<a class="button outline {cls}" href="{esc(wa_url(),quote=True)}" rel="noopener">WhatsApp</a>'
 return out
NAV=[('solutions','Solutions'),('equipment','Equipment'),('case-studies','Case studies'),('resources','Resources'),('support','Support'),('about','About')]
def header(path):
 def active(slug): return path.startswith('/'+slug+'/') or (slug=='resources' and path.startswith('/blog/'))
 nav=''.join(link('/'+slug+'/',title,'active' if active(slug) else '') for slug,title in NAV)
 return f'<a class="skip" href="#main">Skip to content</a><header class="header"><a class="brand" href="/">{B}<span>UNDERWATER SYSTEMS</span></a><button class="menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="navigation"><span class="menu-icon" aria-hidden="true"><span></span></span><span class="menu-text">Menu</span></button><nav id="navigation" aria-label="Main navigation">{nav}<a class="nav-blog" href="/blog/">Blog</a></nav>{button("Get a quote")}</header>'
def mobile_bar():
 wa=f'<a href="{esc(wa_url(),quote=True)}" rel="noopener">WhatsApp</a>' if WHATSAPP else ''
 return f'<div class="mobile-bar" aria-label="Quick contact"><a href="/request-a-proposal/" class="mobile-bar-main">Get a quote</a><a href="mailto:{EMAIL}">Email</a>{wa}</div>'+(f'<a class="wa-float" href="{esc(wa_url(),quote=True)}" rel="noopener" aria-label="Chat on WhatsApp">WhatsApp</a>' if WHATSAPP else '')
def footer():
 contact=f'<a class="contact-email" href="mailto:{EMAIL}">{EMAIL}</a>'
 if PHONE: contact+=f'<a href="tel:{esc(PHONE.replace(" ",""),quote=True)}">{esc(PHONE)}</a>'
 if WHATSAPP: contact+=f'<a href="{esc(wa_url(),quote=True)}" rel="noopener">WhatsApp</a>'
 if ADDRESS: contact+=f'<p>{esc(ADDRESS)}</p>'
 return f'''<footer class="footer"><div class="wrap footer-grid"><div><a class="brand" href="/">{B}<span>UNDERWATER SYSTEMS</span></a><p>Underwater inspection ROVs, cleaning and dredging robots for water infrastructure.</p><p>{COMPANY}</p></div><div><h3>Equipment</h3>{''.join(link('/equipment/'+p['slug']+'/',p['name']+' '+p['kind']) for p in PRODUCTS)}{link('/equipment/compare/','Compare all models')}</div><div><h3>Applications</h3>{''.join(link('/solutions/'+s['slug']+'/',s['seo']) for s in SOLUTIONS)}</div><div><h3>Resources</h3>{link('/blog/','Blog & buying guides')}{link('/resources/','Guides & downloads')}{link('/case-studies/','Manufacturer cases')}{link('/support/','Training & support')}{link('/blog/feed.xml','RSS feed')}</div><div><h3>Contact {B}</h3><p>Equipment selection, quotations<br>and manufacturer coordination.</p>{contact}{link('/request-a-proposal/','Send a project brief')}{link('/about/','About us')}</div></div><div class="wrap footer-bottom"><span>© {B} 2026 · {COMPANY}</span><span>Manufacturer: Boya Gongdao / ROBOOCEAN</span><span>{link('/privacy/','Privacy')} · {link('/terms/','Terms')}</span></div></footer>'''
def cta(title='Bring your project into focus.',text='Share the task, site conditions and required results. We reply by email with the questions, configuration and next steps for a quotation.'):
 return f'<section class="cta"><div class="wrap cta-grid"><div><p class="eyebrow">FROM TASK TO CONFIGURATION</p><h2>{title}</h2><p>{text}</p></div><div class="actions">{contact_buttons()}</div></div></section>'
def faq(rows):
 return '<div class="faq">'+''.join(f'<details><summary>{esc(q)}</summary><p>{esc(a)}</p></details>' for q,a in rows)+'</div>'
def faq_schema(rows):
 return {'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in rows]}
def answer_box(text,label='The short answer'):
 return f'<div class="answer-box"><p class="answer-label">{label}</p><p>{esc(text)}</p></div>'
def alt(p):
 return f'{p["name"]} {p["kind"].lower()}, manufacturer image'
def img(p,cls='',lazy=True,sizes='(max-width: 650px) 100vw, 600px'):
 return picture(p['img'],alt(p),cls=cls,lazy=lazy,sizes=sizes)
def product_card(p):
 return f'<article class="product-card"><a class="product-image" href="/equipment/{p["slug"]}/">{img(p)}</a><div class="product-copy"><span class="eyebrow">{p["kind"]}</span><h3>{link("/equipment/"+p["slug"]+"/",p["name"])}</h3><p>{p["summary"]}</p><div class="card-actions">{link("/equipment/"+p["slug"]+"/","View specs","text-link")}{link("/request-a-proposal/?model="+p["id"],"Get a quote","text-link")}</div></div></article>'
def solutions_cards(items=None,more=False):
 cards=''.join(f'<a class="solution-card" href="/solutions/{s["slug"]}/">{icon(s["icon"])}<span class="number">{s["no"]} / {s["verb"]}</span><h3>{s["seo"]}</h3><p>{s["lead"]}</p><span class="text-link">Explore application</span></a>' for s in (items or SOLUTIONS))
 if more: cards+='<a class="solution-card solution-more" href="/solutions/"><span class="number">ALL APPLICATIONS</span><h3>Not sure where your task fits?</h3><p>See every application, or send a short brief and we will suggest a starting configuration.</p><span class="text-link">View all applications</span></a>'
 return '<div class="solution-grid">'+cards+'</div>'
def intro(label,title,lead,kicker=''):
 k=f'<p class="intro-kicker">{kicker}</p>' if kicker else ''
 return f'<section class="page-intro"><div class="wrap"><p class="eyebrow">{label}</p><h1>{title}</h1>{k}<p class="lead">{lead}</p></div></section>'
def section_list(title,items):
 return f'<h3>{title}</h3><ul class="clean-list">'+''.join('<li>'+esc(i)+'</li>' for i in items)+'</ul>'
def steps(rows):
 return '<div class="steps">'+''.join(f'<article><span>0{i}</span><h3>{t}</h3><p>{d}</p></article>' for i,(t,d) in enumerate(rows,1))+'</div>'
def stat_bar(rows,cls=''):
 return f'<dl class="stat-bar {cls}">'+''.join(f'<div><dt>{v}</dt><dd>{l}</dd></div>' for v,l in rows)+'</dl>'

SYSTEM_DIAGRAM='''<figure class="system-diagram"><svg viewBox="0 0 640 260" role="img" aria-labelledby="sysd-t"><title id="sysd-t">Typical tethered underwater robot system: surface control station and power supply, tether reel, tether and underwater vehicle</title><rect class="sd-water" x="0" y="110" width="640" height="150"/><path class="sd-surface" d="M0 110 Q40 102 80 110 T160 110 T240 110 T320 110 T400 110 T480 110 T560 110 T640 110"/><rect class="sd-box" x="24" y="38" width="112" height="56" rx="4"/><text x="80" y="62" text-anchor="middle">Control</text><text x="80" y="80" text-anchor="middle">station</text><rect class="sd-box" x="156" y="38" width="96" height="56" rx="4"/><text x="204" y="62" text-anchor="middle">Power</text><text x="204" y="80" text-anchor="middle">supply</text><circle class="sd-box" cx="320" cy="72" r="28"/><circle class="sd-hub" cx="320" cy="72" r="8"/><text x="320" y="24" text-anchor="middle">Tether reel</text><path class="sd-link" d="M136 66h20M252 66h40"/><path class="sd-tether" d="M346 82 C400 120 380 180 450 196 S520 186 540 196"/><rect class="sd-vehicle" x="520" y="176" width="92" height="44" rx="6"/><text class="sd-light" x="566" y="203" text-anchor="middle">Vehicle</text><text x="430" y="240" text-anchor="middle">Tether: power + data</text><text x="566" y="166" text-anchor="middle">Sensors / tools</text></svg><figcaption>Every model on this site is a tethered system. Quote and verify the complete package, not the vehicle alone.</figcaption></figure>'''

def crumbs_for(path,title):
 parents={'/solutions/':'Applications','/equipment/':'Equipment','/case-studies/':'Case studies','/resources/':'Resources','/blog/':'Blog'}
 out=[('Home','/')]
 for pre,name in parents.items():
  if path.startswith(pre) and path!=pre: out.append((name,pre))
 if path.endswith('/spec-sheet/'):
  prod=path[:-len('spec-sheet/')]
  out.append((next(p['name'] for p in PRODUCTS if '/equipment/'+p['slug']+'/'==prod),prod))
 if path!='/': out.append((title,path))
 return out
def breadcrumb_schema(parts):
 return {'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':i,'name':n,'item':ORIGIN+u} for i,(n,u) in enumerate(parts,1)]}
def organization():
 org={'@type':'Organization','@id':ORG_ID,'name':C['brand'],'legalName':C['legal_company'],'url':ORIGIN+'/','logo':{'@type':'ImageObject','url':ORIGIN+'/assets/logo.png','width':512,'height':512},'email':C['contact_email'],'description':'Equipment selection, quotation and manufacturer coordination for underwater inspection ROVs, cleaning robots and dredging robots used on water infrastructure.','knowsAbout':['Underwater inspection ROV','Tunnel inspection ROV','Dam inspection','Penstock inspection','Trash rack cleaning robot','Underwater dredging robot'],'contactPoint':{'@type':'ContactPoint','contactType':'sales','email':C['contact_email'],'areaServed':'Worldwide','availableLanguage':['English']}}
 if PHONE: org['telephone']=PHONE;org['contactPoint']['telephone']=PHONE
 if ADDRESS: org['address']=ADDRESS
 if C.get('social_profiles'): org['sameAs']=C['social_profiles']
 return org

def analytics():
 out=''
 if C.get('ga4_id'):
  gid=esc(C['ga4_id'],quote=True)
  out+=f'<script async src="https://www.googletagmanager.com/gtag/js?id={gid}"></script><script>window.dataLayer=window.dataLayer||[];function gtag(){{dataLayer.push(arguments)}}gtag("js",new Date());gtag("config","{gid}");</script>'
 if C.get('plausible_domain'):
  out+=f'<script defer data-domain="{esc(C["plausible_domain"],quote=True)}" src="https://plausible.io/js/script.js"></script>'
 return out

def write(path,title,description,body,noindex=False,schema_extra=None,og_type='website',og_image='ad-400.jpg',lastmod=None,page_title=None):
 assert len(description)<=160, f'{path}: description {len(description)} chars'
 PAGES.append(dict(path=path,title=title,description=description,noindex=noindex,lastmod=lastmod or UPDATED))
 dest=DIST/path.strip('/')/'index.html' if path!='/' else DIST/'index.html'
 dest.parent.mkdir(parents=True,exist_ok=True)
 canonical=f'<link rel="canonical" href="{ORIGIN}{path}">' if ORIGIN else ''
 schema={'@context':'https://schema.org','@type':'WebPage','@id':ORIGIN+path+'#webpage','name':title,'description':description,'url':ORIGIN+path,'inLanguage':'en','isPartOf':{'@id':ORIGIN+'/#website'},'publisher':{'@id':ORG_ID}}
 if path=='/':
  schema=[schema,dict(organization(),**{'@context':'https://schema.org'}),{'@context':'https://schema.org','@type':'WebSite','@id':ORIGIN+'/#website','name':C['brand'],'url':ORIGIN+'/','publisher':{'@id':ORG_ID},'inLanguage':'en'}]
 else:
  schema=[schema]
 extras=list(schema_extra or [])
 if path!='/' and not any(s.get('@type')=='BreadcrumbList' for s in extras): extras.append(breadcrumb_schema(crumbs_for(path,title)))
 ld=''.join('<script type="application/ld+json">'+json.dumps(s,ensure_ascii=False).replace('</','<\\/')+'</script>' for s in schema+extras)
 og=og_image_for(og_image)
 full_title=page_title or f'{title} | {C["brand"]}'
 gsc=f'<meta name="google-site-verification" content="{esc(C["gsc_verification"],quote=True)}">' if C.get('gsc_verification') else ''
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{esc(full_title)}</title><meta name="description" content="{esc(description,quote=True)}">{canonical}
<meta name="robots" content="{'noindex,follow' if noindex else 'index,follow,max-image-preview:large'}"><meta name="theme-color" content="#0b2932">{gsc}
<meta property="og:title" content="{esc(full_title,quote=True)}"><meta property="og:description" content="{esc(description,quote=True)}">
<meta property="og:type" content="{og_type}"><meta property="og:url" content="{ORIGIN}{path}"><meta property="og:site_name" content="{B}"><meta property="og:locale" content="en_US"><meta property="og:image" content="{ORIGIN}/assets/{og}"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630">
<meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{esc(title,quote=True)}"><meta name="twitter:description" content="{esc(description,quote=True)}"><meta name="twitter:image" content="{ORIGIN}/assets/{og}">
<link rel="alternate" type="application/rss+xml" title="PanPan Marine Blog" href="{ORIGIN}/blog/feed.xml">
<link rel="preload" href="/assets/fonts/manrope-latin-800-normal.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="/assets/fonts/dm-sans-latin-400-normal.woff2" as="font" type="font/woff2" crossorigin>
<link rel="icon" type="image/svg+xml" href="/assets/favicon.svg"><link rel="apple-touch-icon" href="/assets/logo.png"><link rel="stylesheet" href="/assets/site.css?v={ASSET_V}"><link rel="stylesheet" href="/assets/blog.css?v={ASSET_V}">
{ld}<script defer src="/assets/site.js?v={ASSET_V}"></script>{analytics()}</head>
<body>{header(path)}<main id="main">{body}</main>{footer()}{mobile_bar()}</body></html>'''
 dest.write_text(html,encoding='utf-8')

