def product_schema(p,path):
 d={'@context':'https://schema.org','@type':'Product','@id':ORIGIN+path+'#product','name':p['seo'],'model':p['name'],'category':p['kind'],'description':p['answer'],'image':[ORIGIN+'/assets/'+p['img'],ORIGIN+'/assets/'+og_image_for(p['img'])],'url':ORIGIN+path,'brand':{'@type':'Brand','name':'ROBOOCEAN'},'manufacturer':{'@type':'Organization','name':'Boya Gongdao (ROBOOCEAN)','url':'https://www.boyagongdao.com/'},'additionalProperty':[{'@type':'PropertyValue','name':k,'value':v} for k,v in p['specs']]}
